#!/usr/bin/env python3
"""Ross's transcript sync: discover Friend-Message commits on all six friend/*
branches and append any not yet published to the correct S*/E*.md file.

Run inside a clean main worktree. Prints a report; writes only when --write.
Verbatim copies only; never edits existing entries.
"""
import os
import re
import subprocess
import sys
from datetime import datetime

REPO = os.environ.get("SYNC_REPO", "/tmp/ross-main")
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
MESSAGE_MARK = "Friend-Message: 1"
SOURCE_RE = re.compile(r"^Source: (friend/[a-z]+) @ ([0-9a-f]{40})\s*$", re.M)

WRITE = "--write" in sys.argv


def git(*args, cwd=REPO):
    return subprocess.run(["git", "-C", cwd, *args], capture_output=True, text=True, check=True).stdout


def discover():
    msgs = {}
    for b in BRANCHES:
        shas = git("rev-list", f"origin/friend/{b}").split()
        for sha in shas:
            body = git("log", "-1", "--format=%B", sha)
            lines = body.split("\n")
            if MESSAGE_MARK not in [l.strip() for l in lines[:6]]:
                continue
            fields = {}
            for l in lines:
                m = re.match(r"^(Speaker|Episode|Reply-To):\s*(.*)$", l)
                if m:
                    fields[m.group(1)] = m.group(2).strip()
            # utterance: text after the blank line that follows the header block
            # find first blank line after the Reply-To line
            idx = next((i for i, l in enumerate(lines) if l.startswith("Reply-To:")), None)
            if idx is None:
                continue
            j = idx + 1
            while j < len(lines) and lines[j].strip() == "":
                j += 1
            utter = "\n".join(lines[j:]).rstrip("\n")
            if not utter:
                continue
            ts = git("log", "-1", "--format=%cI", sha).strip()
            try:
                dtime = datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                dtime = datetime.min
            msgs[sha] = {
                "sha": sha,
                "branch": b,
                "speaker": fields.get("Speaker", b.capitalize()),
                "episode": fields.get("Episode", ""),
                "reply_to": fields.get("Reply-To", "none"),
                "ts": ts,
                "dtime": dtime,
                "text": utter,
            }
    return msgs


def published():
    out = {}
    for root, _dirs, files in os.walk(REPO):
        if os.sep + "." in root:
            continue
        for f in files:
            if not f.endswith(".md"):
                continue
            path = os.path.join(root, f)
            rel = os.path.relpath(path, REPO)
            if not re.match(r"^S\d+/E\d+\.md$", rel):
                continue
            txt = open(path, encoding="utf-8").read()
            for m in SOURCE_RE.finditer(txt):
                out[m.group(2)] = rel
    return out


def entry_text(m):
    return "\n".join(
        [
            f"**{m['speaker']}** ({m['ts']})",
            "",
            f"Source: friend/{m['branch']} @ {m['sha']}",
            "",
            m["text"],
        ]
    )


def order_batch(batch):
    """commit time, then sha for ties; honor Reply-To when both in batch."""
    by_sha = {m["sha"]: m for m in batch}
    ordered = []
    remaining = sorted(batch, key=lambda m: (m["dtime"], m["sha"]))
    while remaining:
        progressed = False
        for m in list(remaining):
            parent = by_sha.get(m["reply_to"])
            if parent is None or parent in ordered:
                ordered.append(m)
                remaining.remove(m)
                progressed = True
        if not progressed:  # cycle: fall back to time order
            ordered.extend(remaining)
            break
    return ordered


def main():
    msgs = discover()
    pub = published()
    missing = [m for sha, m in msgs.items() if sha not in pub]
    by_ep = {}
    for m in missing:
        by_ep.setdefault(m["episode"], []).append(m)
    print(f"discovered {len(msgs)} messages, {len(pub)} published SHAs, {len(missing)} missing")
    for ep in sorted(by_ep):
        batch = order_batch(by_ep[ep])
        print(f"\n--- {ep}: {len(batch)} missing")
        for m in batch:
            print(f"  {m['ts']} {m['speaker']:<8} {m['sha'][:12]} reply={m['reply_to'][:12]}")
            print("      " + m["text"].replace("\n", "\n      ")[:160])
        if not WRITE:
            continue
        path = os.path.join(REPO, ep + ".md")
        if not os.path.exists(path):
            print(f"  !! no file for {ep}; create frontmatter manually")
            continue
        with open(path, "a", encoding="utf-8") as fh:
            txt = open(path, encoding="utf-8").read()
            if not txt.endswith("\n"):
                fh.write("\n")
            for m in batch:
                fh.write("\n" + entry_text(m) + "\n")
        print(f"  appended {len(batch)} entries to {path}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Integrity validator for the Friends transcript on main.

Checks every published entry against the source commit it cites, verifies
completeness against all six friend/* branches, and validates episode
frontmatter/summaries. Read-only.
"""
import os
import re
import subprocess
import sys
from datetime import datetime, timezone

REPO = os.environ.get("SYNC_REPO", "/tmp/ross-main")
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
ENTRY_RE = re.compile(
    r"^\*\*(?P<sp>[A-Za-z]+)\*\* \((?P<ts>[0-9T:\-+Z.]+)\)\n\n"
    r"Source: friend/(?P<br>[a-z]+) @ (?P<sha>[0-9a-f]{40})\n\n"
    r"(?P<text>.*?)(?=\n\n\*\*[A-Za-z]+\*\* \([0-9T:\-+Z.]+\)\n\nSource: |\Z)",
    re.M | re.S,
)

problems = []
notes = []


def git(*args):
    return subprocess.run(["git", "-C", REPO, *args], capture_output=True, text=True).stdout


def discover():
    msgs, bodies = {}, {}
    for b in BRANCHES:
        for sha in git("rev-list", f"origin/friend/{b}").split():
            body = bodies[sha] = git("log", "-1", "--format=%B", sha)
            lines = body.split("\n")
            if "Friend-Message: 1" not in [l.strip() for l in lines[:6]]:
                continue
            fields = dict(
                re.findall(r"^(Speaker|Episode|Reply-To):\s*(.*)$", body, re.M)
            )
            idx = next((i for i, l in enumerate(lines) if l.startswith("Reply-To:")), None)
            if idx is None:
                problems.append(f"{sha}: no Reply-To line")
                continue
            j = idx + 1
            while j < len(lines) and lines[j].strip() == "":
                j += 1
            msgs[sha] = {
                "sha": sha,
                "branch": b,
                "speaker": fields.get("Speaker", "").strip(),
                "episode": fields.get("Episode", "").strip(),
                "reply_to": fields.get("Reply-To", "none").strip(),
                "ts": git("log", "-1", "--format=%cI", sha).strip(),
                "text": "\n".join(lines[j:]).rstrip("\n"),
                "body": body,
            }
    return msgs


def check_summary(path, rel):
    txt = open(path, encoding="utf-8").read()
    m = re.match(r"^---\n(.*?)\n---\n\n(.*?)\n\n\*\*", txt, re.S)
    if not m:
        problems.append(f"{rel}: cannot parse frontmatter/summary block")
        return
    fm, para = m.group(1), m.group(2)
    fields = dict(re.findall(r"^(\w+):\s*(.*)$", fm, re.M))
    for key in ("title", "summary", "season", "episode", "status"):
        if key not in fields:
            problems.append(f"{rel}: frontmatter missing {key}")
    season, episode = rel.split("/")
    if fields.get("season") != season[-2:].lstrip("0"):
        problems.append(f"{rel}: season frontmatter {fields.get('season')} != {season}")
    if fields.get("episode") != episode[1:].lstrip("0"):
        problems.append(f"{rel}: episode frontmatter {fields.get('episode')} != {episode}")
    if fields.get("status") not in ("ongoing", "complete"):
        problems.append(f"{rel}: bad status {fields.get('status')}")
    s = fields.get("summary", "").strip()
    if not (s.startswith('"') and s.endswith('"')):
        problems.append(f"{rel}: summary not quoted")
    s_val = s.strip('"')
    if s_val != para.strip():
        problems.append(f"{rel}: summary paragraph does not match frontmatter")
    words = len(s_val.split())
    if not (10 <= words <= 45):
        notes.append(f"{rel}: summary is {words} words")
    for bad in ("commit", "agent", "transcript", "model", "branch", "prompt"):
        if re.search(rf"\b{bad}", s_val, re.I):
            problems.append(f"{rel}: summary mentions '{bad}'")
    if not re.match(r'^title: "The One With ', fm, re.M):
        notes.append(f"{rel}: title not in 'The One With ...' style")


def main():
    msgs = discover()
    total_entries = 0
    seen = {}
    files = sorted(
        os.path.join(r, f)
        for r, _d, fs in os.walk(REPO)
        for f in fs
        if re.match(r"^S\d+$", os.path.basename(r)) and re.match(r"^E\d+\.md$", f)
    )
    for path in files:
        rel = os.path.relpath(path, REPO)
        check_summary(path, rel)
        txt = open(path, encoding="utf-8").read()
        body_start = txt.index("**")
        body = txt[body_start:]
        matches = list(ENTRY_RE.finditer(body))
        tail = body[matches[-1].end():] if matches else body
        if tail.strip():
            problems.append(f"{rel}: trailing text outside an entry: {tail.strip()[:60]!r}")
        prev = None
        for m in matches:
            total_entries += 1
            sha, br, sp, ts, text = (
                m.group("sha"),
                m.group("br"),
                m.group("sp"),
                m.group("ts"),
                m.group("text").rstrip("\n"),
            )
            src = msgs.get(sha)
            if src is None:
                problems.append(f"{rel}: unknown source commit {sha} (claimed {sp})")
                continue
            if sha in seen:
                problems.append(f"{rel}: duplicate entry {sha} (also {seen[sha]})")
            seen[sha] = rel
            if src["text"] != text:
                problems.append(f"{rel}: text mismatch for {sha}\n  file: {text!r}\n  src : {src['text']!r}")
            if src["speaker"] != sp:
                problems.append(f"{rel}: speaker mismatch {sp} != {src['speaker']} for {sha}")
            if src["branch"] != br:
                problems.append(f"{rel}: branch mismatch friend/{br} != friend/{src['branch']} for {sha}")
            if src["ts"] != ts:
                problems.append(f"{rel}: timestamp mismatch {ts} != {src['ts']} for {sha}")
            if src["episode"] and src["episode"] != rel[:-3]:
                problems.append(f"{rel}: declared episode {src['episode']} for {sha}")
            # ordering
            key = (src["ts"], sha)
            if prev and key < prev:
                problems.append(f"{rel}: out of order at {sha[:12]} ({ts}) after {prev[1][:12]}")
            if prev and src["reply_to"] == prev[1] and key < prev[0]:
                pass
            prev = (key, sha)
        # reply-to after reply ordering
        idx_of = {m.group("sha"): i for i, m in enumerate(matches)}
        for i, m in enumerate(matches):
            parent = msgs.get(m.group("sha"), {}).get("reply_to", "none")
            if parent in idx_of and idx_of[parent] > i:
                problems.append(f"{rel}: {m.group('sha')[:12]} appears before its parent {parent[:12]}")

    missing = [s for s in msgs if s not in seen]
    print(f"files: {len(files)}  entries: {total_entries}  messages on branches: {len(msgs)}")
    print(f"missing from transcript: {len(missing)}")
    for s in sorted(missing, key=lambda s: msgs[s]["ts"]):
        print(f"  MISSING {msgs[s]['ts']} {msgs[s]['speaker']:<8} {msgs[s]['episode']} {s[:12]}")
    print(f"problems: {len(problems)}")
    for p in problems[:40]:
        print("  !!", p)
    print(f"notes: {len(notes)}")
    for n in notes[:10]:
        print("  ~", n)
    return 1 if problems or missing else 0


if __name__ == "__main__":
    sys.exit(main())

